"""Public policy language: lexical form, grammar and declared per-string bounds.

The module performs no predicate evaluation and builds no automata; it turns a
policy string into a rule list ``[(predicate, allow), ...]`` and reports the
atom/path-service occurrence counts used by the whole-request budget.

Grammar (the only ignored whitespace between tokens is space, tab, form feed,
CR and LF)::

    policy*      := (predicate action ";")*
    predicate    := "(" predicate ("and"|"or") predicate ")"
                  | "not" "(" predicate ")"
                  | atom
    atom         := ("match"|"startswith"|"endswith"|"contains") "(" [NAME ("," NAME)*] ")"
    action       := "allow" | "drop"
    NAME         := [A-Za-z][A-Za-z0-9]{0,23}

Scanning is positional and context aware, exactly like the supplied Lark LALR
setup: no separator is required between two tokens, so an operator keyword may
run straight into the following atom (``(match(A)andmatch(B))``), while a path
position only ever accepts whole identifiers, never keywords.

Declared bounds (violations reject that policy):

* predicate nesting depth at most 16, an atom has depth 1;
* every path has at most 16 services, a non-``match`` atom at most 4;
* at most 8 rules whose predicate is not a single ``match`` atom, each such
  predicate holding at most 32 atom occurrences;
* at most 4 distinct non-``match`` atoms per string;
* at most 32768 atom occurrences and 65536 path-service occurrences per string.
"""

__all__ = ['PolicyError', 'RegistryError', 'parse', 'check_registry', 'rule_atoms',
           'MAX_ATOMS', 'MAX_PATH_SERVICES', 'MAX_DEPTH', 'MAX_PATH',
           'MAX_COMPLEX_RULES', 'MAX_COMPLEX_ATOMS', 'MAX_DISTINCT_NONLITERAL',
           'MAX_NONLITERAL_PATH', 'MAX_NAME_LENGTH', 'ATOM_KINDS', 'WS']

ATOM_KINDS = ('match', 'startswith', 'endswith', 'contains')
WS = ' \t\f\r\n'
MAX_NAME_LENGTH = 24
MAX_DEPTH = 16
MAX_PATH = 16
MAX_COMPLEX_RULES = 8
MAX_COMPLEX_ATOMS = 32
MAX_DISTINCT_NONLITERAL = 4
MAX_NONLITERAL_PATH = 4
MAX_ATOMS = 32768
MAX_PATH_SERVICES = 65536
# A policy that satisfies every bound above needs far fewer tokens than this,
# so the cap only stops a hostile string from exhausting time and memory.
MAX_TOKENS = 500000

_PREDICATE_WORDS = ('startswith', 'endswith', 'contains', 'match', 'not')
_OPERATORS = ('and', 'or')
_ACTIONS = ('allow', 'drop')
_LONGEST_FIRST = tuple(sorted(_PREDICATE_WORDS + _OPERATORS + _ACTIONS, key=len, reverse=True))


class PolicyError(ValueError):
    """Syntax or declared policy-bound violation; rejects that stage event."""


class RegistryError(PolicyError):
    """Syntactically valid policy naming a service the registry does not have."""


def _is_letter(char):
    return 'a' <= char <= 'z' or 'A' <= char <= 'Z'


def _is_name_char(char):
    return _is_letter(char) or '0' <= char <= '9'


class _Parser:
    """Positional context-aware scanner with a recursive descent parser."""

    __slots__ = ('text', 'length', 'position', 'atoms', 'symbols', 'nonliteral',
                 'complex', 'rules', 'tokens')

    def __init__(self, text):
        self.text = text
        self.length = len(text)
        self.position = 0
        self.atoms = 0
        self.symbols = 0
        self.nonliteral = set()
        self.complex = 0
        self.rules = []
        self.tokens = 0

    def fail(self, what):
        raise PolicyError(what)

    def counted(self):
        self.tokens += 1
        if self.tokens > MAX_TOKENS:
            self.fail('token budget')

    def skip(self):
        text = self.text
        position = self.position
        length = self.length
        while position < length and text[position] in WS:
            position += 1
        self.position = position

    def at_end(self):
        self.skip()
        return self.position >= self.length

    def literal(self, token):
        """Punctuation or a keyword that must not be confused with a name."""
        self.skip()
        if self.text.startswith(token, self.position):
            self.position += len(token)
            self.counted()
            return True
        return False

    def word(self, candidates):
        """Longest acceptable keyword, mirroring the contextual terminal set."""
        self.skip()
        best = None
        for candidate in _LONGEST_FIRST:
            if candidate in candidates and self.text.startswith(candidate, self.position):
                best = candidate
                break
        if best is None:
            return None
        self.position += len(best)
        self.counted()
        return best

    def name(self):
        """Whole maximal identifier; keywords are ordinary names here."""
        self.skip()
        text = self.text
        position = self.position
        length = self.length
        if position >= length or not _is_letter(text[position]):
            return None
        end = position + 1
        while end < length and _is_name_char(text[end]):
            end += 1
        self.position = end
        self.counted()
        name = text[position:end]
        if len(name) > MAX_NAME_LENGTH:
            self.fail('name form')
        return name

    def predicate(self, depth):
        if depth > MAX_DEPTH:
            self.fail('predicate depth')
        if self.at_end():
            self.fail('predicate')
        self.skip()
        if self.literal('('):
            left = self.predicate(depth + 1)
            operator = self.word(_OPERATORS)
            if operator is None:
                self.fail('binary operator')
            right = self.predicate(depth + 1)
            if not self.literal(')'):
                self.fail('closing parenthesis')
            return (operator, left, right)
        if self.literal('not'):
            if not self.literal('('):
                self.fail('not parenthesis')
            inner = self.predicate(depth + 1)
            if not self.literal(')'):
                self.fail('closing parenthesis')
            return ('not', inner)
        kind = self.word(ATOM_KINDS)
        if kind is None:
            self.fail('atom')
        if not self.literal('('):
            self.fail('atom parenthesis')
        path = self.path()
        if not self.literal(')'):
            self.fail('closing parenthesis')
        if len(path) > MAX_PATH:
            self.fail('path length')
        self.atoms += 1
        self.symbols += len(path)
        if kind != 'match':
            if len(path) > MAX_NONLITERAL_PATH:
                self.fail('nonliteral path length')
            self.nonliteral.add((kind, path))
        return (kind, path)

    def path(self):
        path = []
        name = self.name()
        if name is None:
            return ()
        path.append(name)
        while self.literal(','):
            name = self.name()
            if name is None:
                self.fail('path name')
            path.append(name)
            if len(path) > MAX_PATH:
                self.fail('path length')
        return tuple(path)

    def run(self):
        while not self.at_end():
            predicate = self.predicate(1)
            action = self.word(_ACTIONS)
            if action is None:
                self.fail('action')
            if not self.literal(';'):
                self.fail('rule terminator')
            if predicate[0] != 'match':
                self.complex += 1
                if self.complex > MAX_COMPLEX_RULES:
                    self.fail('complex rule count')
                if rule_atoms(predicate) > MAX_COMPLEX_ATOMS:
                    self.fail('complex rule atoms')
            if self.atoms > MAX_ATOMS or self.symbols > MAX_PATH_SERVICES:
                self.fail('occurrence budget')
            if len(self.nonliteral) > MAX_DISTINCT_NONLITERAL:
                self.fail('distinct nonliteral atoms')
            self.rules.append((predicate, action == 'allow'))
        return self.rules, self.atoms, self.symbols


def parse(text):
    """Return ``(rules, atom_occurrences, path_service_occurrences)``.

    ``rules`` is a list of ``(predicate, allow)`` pairs; a predicate is a nested
    tuple whose leaves are ``(kind, path)`` with ``path`` a tuple of service
    names.  Raises PolicyError for syntax and policy-bound violations.
    """
    if type(text) is not str:
        raise PolicyError('policy type')
    try:
        text.encode('utf-8')
    except UnicodeEncodeError as exc:
        raise PolicyError('surrogate') from exc
    return _Parser(text).run()


def rule_atoms(predicate):
    """Number of atom occurrences inside one predicate."""
    total = 0
    stack = [predicate]
    while stack:
        node = stack.pop()
        kind = node[0]
        if kind in ATOM_KINDS:
            total += 1
        elif kind == 'not':
            stack.append(node[1])
        else:
            stack.append(node[1])
            stack.append(node[2])
    return total


def check_registry(rules, names):
    """Raise RegistryError when a predicate names a service outside ``names``."""
    stack = [predicate for predicate, _ in rules]
    while stack:
        node = stack.pop()
        kind = node[0]
        if kind in ATOM_KINDS:
            for name in node[1]:
                if name not in names:
                    raise RegistryError('unregistered service %r' % (name,))
        elif kind == 'not':
            stack.append(node[1])
        else:
            stack.append(node[1])
            stack.append(node[2])
